@Transactional
public void processUserLifecycle(EntityManager em) {
    // 1. Find an existing entity (Managed state)
    User user = em.find(User.class, 1L);
    user.setEmail("new.email@domain.com");

    // 2. Persist a brand new transient entity
    User newUser = new User("Alice", "alice@domain.com");
    em.persist(newUser);

    // 3. Merge a detached entity (e.g., received from a REST payload)
    User detachedUser = new User(2L, "Bob", "bob@domain.com");
    User managedBob = em.merge(detachedUser);

    // 4. Remove an entity
    User doomedUser = em.find(User.class, 3L);
    if (doomedUser != null) {
        em.remove(doomedUser);
    }
}
